    ctx->prev_cmd[0] = 0;
    ctx->prev_cmd[1] = 0;
    if (lo)
       av_dlog(ctx, "(%c,%c)\n",hi,lo);
    else
       av_dlog(ctx, "(%c)\n",hi);
}


