int opt_default(const char *opt, const char *arg)
{
    const AVOption *oc, *of, *os, *oswr;
    char opt_stripped[128];
    const char *p;
    const AVClass *cc = avcodec_get_class(), *fc = avformat_get_class(), *sc, *swr_class;

    if (!(p = strchr(opt, ':')))
        p = opt + strlen(opt);
